SELECT /*+ PARTITION(${partition}) */ * 
FROM ods_rt_szdn_snapshot_flow_addcode 
WHERE big_id = #{bigId} 
  AND snapshottime = #{snapshottime}

SELECT * 
FROM ods_rt_szdn_snapshot_flow_addcode 
WHERE big_id = #{bigId} 
  AND snapshottime BETWEEN #{startTime} AND #{endTime}

SELECT /*+ PARTITION(${partition}) */ * 
FROM ods_rt_szdn_snapshot_flow_addcode 
WHERE snapshottime BETWEEN #{startTime} AND #{endTime}
ORDER BY snapshottime ASC
LIMIT #{offset}, #{limit}

SELECT /*+ PARTITION(${partition}) */ COUNT(*) 
FROM ods_rt_szdn_snapshot_flow_addcode 
WHERE snapshottime BETWEEN #{startTime} AND #{endTime}

SELECT * 
FROM ods_rt_szdn_snapshot_flow_addcode 
WHERE snapshottime BETWEEN #{startTime} AND #{endTime}
ORDER BY snapshottime ASC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) 
FROM ods_rt_szdn_snapshot_flow_addcode 
WHERE snapshottime BETWEEN #{startTime} AND #{endTime}
